/* setCommCode */
INSERT INTO TM_CODEXM (
            COMM_CODE
          , CODE_NAME
          , CODE_EXPL
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{commCode}
          , #{codeName}
          , #{codeExpl,jdbcType=VARCHAR}
          , #{useeYsno}
          , #{regiAdmn}
          , SYSDATE
          , #{updtAdmn}
          , SYSDATE
)

mapper.update:
UPDATE /* uptCommCode */
       TM_CODEXM
   SET CODE_NAME = #{codeName}
     , CODE_EXPL = #{codeExpl,jdbcType=VARCHAR}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = SYSDATE
 WHERE COMM_CODE = #{commCode}

mapper.select:
SELECT /* getComdCodeCnt */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{commCode}
   AND COMD_CODE = #{comdCode}

mapper.insert:
/* setComdCode */
INSERT INTO TB_CODEXD (
            COMM_CODE
          , COMD_CODE
          , COMD_NAME
          , CODE_EXPL
          , OPT1_CODE
          , OPT1_NAME
          , OPT2_CODE
          , OPT2_NAME
          , OPT3_CODE
          , OPT3_NAME
          , OPT4_CODE
          , OPT4_NAME
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
          , SORT_ORDR
) VALUES (  #{commCode}
          , #{comdCode}
          , #{comdName}
          , #{codeExpl,jdbcType=VARCHAR}
          , #{opt1Code,jdbcType=VARCHAR}
          , #{opt1Name,jdbcType=VARCHAR}
          , #{opt2Code,jdbcType=VARCHAR}
          , #{opt2Name,jdbcType=VARCHAR}
          , #{opt3Code,jdbcType=VARCHAR}
          , #{opt3Name,jdbcType=VARCHAR}
          , #{opt4Code,jdbcType=VARCHAR}
          , #{opt4Name,jdbcType=VARCHAR}
          , #{useeYsno}
          , #{regiAdmn}
          , SYSDATE
          , #{updtAdmn}
          , SYSDATE
          , #{sortOrdr,jdbcType=NUMERIC}
)

mapper.update:
UPDATE /* uptComdCode */
       TB_CODEXD
   SET COMD_NAME = #{comdName}
     , CODE_EXPL = #{codeExpl,jdbcType=VARCHAR}
     , OPT1_CODE = #{opt1Code,jdbcType=VARCHAR}
     , OPT1_NAME = #{opt1Name,jdbcType=VARCHAR}
     , OPT2_CODE = #{opt2Code,jdbcType=VARCHAR}
     , OPT2_NAME = #{opt2Name,jdbcType=VARCHAR}
     , OPT3_CODE = #{opt3Code,jdbcType=VARCHAR}
     , OPT3_NAME = #{opt3Name,jdbcType=VARCHAR}
     , OPT4_CODE = #{opt4Code,jdbcType=VARCHAR}
     , OPT4_NAME = #{opt4Name,jdbcType=VARCHAR}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = SYSDATE
     , SORT_ORDR = #{sortOrdr,jdbcType=NUMERIC}
 WHERE COMM_CODE = #{commCode}
   AND COMD_CODE = #{comdCode}

mapper.delete:
DELETE /* delComdCode */
  FROM TB_CODEXD
 WHERE COMM_CODE = #{commCode}
   AND COMD_CODE = #{comdCode}

mapper.select:

SELECT /* getCodeName */
       COMD_NAME
  FROM TB_CODEXD
 WHERE COMM_CODE = #{commCode}
   AND COMD_CODE = #{comdCode}
   AND NVL(USEE_YSNO, #{yes}) = #{yes}


SELECT /* getCodeNameByComdCode */
       C.COMD_NAME
  FROM (  SELECT D.COMD_NAME
           FROM TB_CODEXD D
          WHERE D.COMD_CODE = #{comdCode}
            AND NVL(D.USEE_YSNO, #{yes}) = #{yes}
       ORDER BY D.COMM_CODE
       ) C
 WHERE ROWNUM = 1
